class Solution {
    public int[] sortColours(int[] balls) {
        int[] count = new int[3];
        for (int b : balls) count[b]++;
        int[] out = new int[balls.length];
        int w = 0;
        for (int c = 0; c < 3; c++) for (int i = 0; i < count[c]; i++) out[w++] = c;
        return out;
    }
}

