class Solution:
    def sortColours(self, balls: List[int]) -> List[int]:
        a = balls[:]
        lo, mid, hi = 0, 0, len(a) - 1
        while mid <= hi:
            if a[mid] == 0:
                a[lo], a[mid] = a[mid], a[lo]
                lo += 1
                mid += 1
            elif a[mid] == 2:
                a[mid], a[hi] = a[hi], a[mid]
                hi -= 1
            else:
                mid += 1
        return a

