class Solution {
    public int[] sortColours(int[] balls) {
        int[] a = balls.clone();
        int lo = 0, mid = 0, hi = a.length - 1;
        while (mid <= hi) {
            if (a[mid] == 0) { int t = a[lo]; a[lo++] = a[mid]; a[mid++] = t; }
            else if (a[mid] == 2) { int t = a[hi]; a[hi--] = a[mid]; a[mid] = t; }
            else mid++;
        }
        return a;
    }
}

