class Solution {
public:
    vector<int> sortColours(vector<int>& balls) {
        vector<int> a = balls;
        int lo = 0, mid = 0, hi = (int) a.size() - 1;
        while (mid <= hi) {
            if (a[mid] == 0) swap(a[lo++], a[mid++]);
            else if (a[mid] == 2) swap(a[mid], a[hi--]);
            else mid++;
        }
        return a;
    }
};

